// Domain: plain Java
public class Order {
    private OrderStatus status;
    public void pay() {
        if (status != OrderStatus.CREATED) throw new IllegalStateException("Order cannot be paid");
        status = OrderStatus.PAID;
    }
}

public interface OrderStore { Order find(Long id); void save(Order order); }   // owned by the domain

public class PayOrder {                                // use case
    private final OrderStore orders;
    public PayOrder(OrderStore orders) { this.orders = orders; }
    public void execute(Long id) {
        Order order = orders.find(id);
        order.pay();
        orders.save(order);
    }
}

