package com.shop.domain;
import org.springframework.stereotype.Service;
import jakarta.persistence.Entity;

// RIGHT: no framework imports in the domain;
// adapters in other packages import the domain, never the reverse

// Output port (domain)
public interface OrderRepositoryPort {
    Order save(Order order);
}

// Use case (domain, no framework dependency)
public class CompleteOrder {
    private final OrderRepositoryPort orders;
    public CompleteOrder(OrderRepositoryPort orders) { this.orders = orders; }
    public Order execute(Order o) { o.complete(); return orders.save(o); }
}

// Adapter (infrastructure)
@Repository
class OrderJpaAdapter implements OrderRepositoryPort {
    private final OrderJpaRepository jpa;
    public Order save(Order o) { return jpa.save(OrderEntity.from(o)).toDomain(); }
}

